const g={fullName:()=>[{validator:(i,e)=>new Promise((n,r)=>{const s=/^[\p{L}\s.,!?]+$/u,o=/^[0-9]/,t=(e||"").trim();if(!t)return r(new Error("Vui lòng nhập họ và tên"));if(o.test(e))return r(new Error("Không được bắt đầu bằng số"));if(t.length<2||t.length>50)return r(new Error("Họ tên phải từ 2 đến 50 ký tự"));if(!s.test(e))return r(new Error("Họ tên không đúng định dạng"));n("")})}],code:()=>[{required:!0,message:"Vui lòng nhập mã"},{min:3,message:"Tối thiểu 3 ký tự"},{max:10,message:"Tối đa 10 ký tự"}],email:()=>[{validator:(i,e)=>e?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)?Promise.resolve():Promise.reject("Email không đúng định dạng"):Promise.reject("Vui lòng nhập email")}],phone:()=>[{validator:(i,e)=>e?/^(0|\+84)[0-9]{9,10}$/.test(e)?Promise.resolve():Promise.reject("Số điện thoại không đúng"):Promise.reject("Vui lòng nhập số điện thoại")}],address:()=>[{required:!0,message:"Vui lòng nhập địa chỉ"}]};export{g as f};
